    private const string ExampleInput = "..@@.@@@@.\n@@@.@.@.@@\n@@@@@.@.@@\n@.@@@@..@.\n@@.@@@@.@@\n.@@@@@@@.@\n.@.@.@.@@@\n@.@@@.@@@@\n.@@@@@@@@.\n@.@.@@@.@.";

    public int GetResultPartOne()
    {
        char[][] matrix = MyInput.Split('\n').Select(s => s.ToCharArray()).ToArray();
        
        for (int y = 0; y < matrix.Length; y++)
        {
            char[] row = matrix[y];

            for (int x = 0; x < row.Length; x++)
            {
                if (HasLessThanFourAdjacentRolls(matrix, x, y))
                {
                    m_result++;
                }
            }
        }

        return m_result;
    }
    
    public int GetResultPartTwo()
    {
        char[][] matrix = MyInput.Split('\n').Select(s => s.ToCharArray()).ToArray();

        List<(int, int)> removedRolls;

        do
        {
            removedRolls = [];
            for (int y = 0; y < matrix.Length; y++)
            {
                char[] row = matrix[y];

                for (int x = 0; x < row.Length; x++)
                {
                    if (HasLessThanFourAdjacentRolls(matrix, x, y))
                    {
                        removedRolls.Add((x, y));
                        m_result++;
                    }
                }
            }
            
            foreach ((int x, int y) in removedRolls)
            {
                matrix[y][x] = '.';
            }
            
        } while (removedRolls.Count != 0);
        
        return m_result;
    }

    private static bool HasLessThanFourAdjacentRolls(char[][] matrix, int x, int y)
    {
        if (matrix[y][x] == '.') return false;
        
        // l = left, m = mid, r = right
        // u = up, m = mid, d = down
        int lu = y == 0 || x == 0 ? 0 : matrix[y-1][x-1] == '@' ?  1 : 0;
        int mu = y == 0 ? 0 : matrix[y-1][x] == '@' ? 1 : 0;
        int ru = y == 0 ||matrix[y].Length - 1 == x ? 0 : matrix[y-1][x+1] == '@' ?  1 : 0;
        
        int lm = x == 0 ? 0 : matrix[y][x-1] == '@' ?  1 : 0;
        int rm = matrix[y].Length - 1 == x ? 0 : matrix[y][x+1] == '@' ?  1 : 0;
        
        int ld = y == matrix.Length - 1 || x == 0 ? 0 : matrix[y+1][x-1] == '@' ?  1 : 0;
        int md = y == matrix.Length - 1 ? 0 : matrix[y+1][x] == '@' ? 1 : 0;
        int rd = y == matrix.Length - 1 || matrix[y].Length - 1 == x ? 0 : matrix[y+1][x+1] == '@' ?  1 : 0;

        return lu + mu + ru + lm + rm + ld + md + rd < 4;
    }
